/// <summary>
/// One piece of feedback as the worker sees it again: what they sent, and the team's status and reply.
/// </summary>
[DataContractAttribute]
class HSMobileOpsFeedbackItem
{
    str feedbackId;
    str submittedUtc;
    str screen;
    str feedbackType;
    str message;
    str status;
    str response;
}

Method.Source:
[DataMemberAttribute('FeedbackId')]
public str parmFeedbackId(str _value = feedbackId)
{
    feedbackId = _value;
    return feedbackId;
}

[DataMemberAttribute('SubmittedUtc')]
public str parmSubmittedUtc(str _value = submittedUtc)
{
    submittedUtc = _value;
    return submittedUtc;
}

[DataMemberAttribute('Screen')]
public str parmScreen(str _value = screen)
{
    screen = _value;
    return screen;
}

[DataMemberAttribute('FeedbackType')]
public str parmFeedbackType(str _value = feedbackType)
{
    feedbackType = _value;
    return feedbackType;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

[DataMemberAttribute('Status')]
public str parmStatus(str _value = status)
{
    status = _value;
    return status;
}

[DataMemberAttribute('Response')]
public str parmResponse(str _value = response)
{
    response = _value;
    return response;
}
